"""Autodesk Fusion native design authoring; the input is generated by prepare.py."""
import json
import traceback
from pathlib import Path
import adsk.core as core
import adsk.fusion as fusion


def transform(columns, origin):
    matrix = core.Matrix3D.create()
    for row in range(3):
        for col in range(3):
            matrix.setCell(row, col, columns[col][row])
        matrix.setCell(row, 3, origin[row] / 10)
    return matrix


def axes(start, end):
    delta = [b-a for a,b in zip(start,end)]
    length = sum(x*x for x in delta)**.5
    direction = [v/length for v in delta]
    up = [0,1,0] if abs(direction[2])>.98 else [0,0,1]
    cross = [up[1]*direction[2]-up[2]*direction[1],up[2]*direction[0]-up[0]*direction[2],up[0]*direction[1]-up[1]*direction[0]]
    norm = sum(v*v for v in cross)**.5
    first = [v/norm for v in cross]
    second = [direction[1]*first[2]-direction[2]*first[1],direction[2]*first[0]-direction[0]*first[2],direction[0]*first[1]-direction[1]*first[0]]
    return [first,second,direction],length


def finish(design, job, role, appearance_cache):
    if role not in appearance_cache:
        rgb = bytes.fromhex(job["palette"][role][1:])
        base = core.Application.get().materialLibraries.itemByName("Fusion Appearance Library").appearances.itemByName("Plastic - Matte (Gray)")
        ap = design.appearances.addByCopy(base, "FRC " + role)
        for prop_id in ("opaque_albedo","surface_albedo"):
            prop = core.ColorProperty.cast(ap.appearanceProperties.itemById(prop_id))
            if prop:
                prop.value = core.Color.create(*rgb,255)
        appearance_cache[role] = ap
    return appearance_cache[role]


def build_part(root, design, item, appearance_cache, job):
    if item["shape"] == "box":
        a,b=item["lower"],item["upper"]
        start=[(a[0]+b[0])/2,(a[1]+b[1])/2,a[2]]
        end=[start[0],start[1],b[2]]
        width,height=b[0]-a[0],b[1]-a[1]
    else:
        start,end=item["start"],item["end"]
        width,height=item.get("width"),item.get("height")
    basis,length=axes(start,end)
    o=root.occurrences.addNewComponent(transform(basis,start))
    comp=o.component
    comp.name=item["name"]
    sk=comp.sketches.add(comp.xYConstructionPlane)
    sk.name="Editable cross section"
    p=core.Point3D.create
    if item["shape"]=="cylinder":
        sk.sketchCurves.sketchCircles.addByCenterRadius(p(0,0,0),item["radius"]/10)
    else:
        for inset in ([0,item["wall"]] if item["shape"]=="tube" else [0]):
            x=(width/2-inset)/10
            y=(height/2-inset)/10
            sk.sketchCurves.sketchLines.addTwoPointRectangle(p(-x,-y,0),p(x,y,0))
    for hx,hy,radius in item.get("holes",[]):
        sk.sketchCurves.sketchCircles.addByCenterRadius(p((hx-start[0])/10,(hy-start[1])/10,0),radius/10)
    profile=max(sk.profiles,key=lambda v: v.profileLoops.count)
    features=comp.features.extrudeFeatures
    ext=features.addSimple(profile,core.ValueInput.createByString(str(length)+" mm"),fusion.FeatureOperations.NewBodyFeatureOperation)
    ext.name="Stock length"
    body=comp.bRepBodies.item(0)
    body.name=item["name"]
    body.appearance=finish(design,job,item["role"],appearance_cache)
    comp.attributes.add("FRC","source","Project-drawn geometry")
    return o


def run(context):
    job=json.loads(Path("INPUT_MANIFEST_JSON").read_bytes())
    dest=Path(job["output"])
    app=core.Application.get()
    prior=app.activeDocument
    own=None
    receipt={"stage":"open","errors":[]}
    progress=dest/"fusion-progress.json"
    def save(step):
        receipt["stage"]=step
        progress.write_text(json.dumps(receipt,indent=2),encoding="utf8")
    try:
        own=app.documents.add(core.DocumentTypes.FusionDesignDocumentType)
        own.name="REBUILT own-zone R1"
        design=fusion.Design.cast(own.products.itemByProductType("DesignProductType"))
        if hasattr(design,"designIntent") and hasattr(fusion,"DesignIntentTypes"):
            design.designIntent=fusion.DesignIntentTypes.HybridDesignIntentType
        design.designType=fusion.DesignTypes.ParametricDesignType
        root=design.rootComponent
        appearances={}
        for item in job["items"]:
            build_part(root,design,item,appearances,job)
        proxies=[build_part(root,design,item,appearances,job) for item in job["proxies"]]
        exp=design.exportManager
        def archive(name):
            if not exp.execute(exp.createFusionArchiveExportOptions(str(dest/name))):
                raise RuntimeError("Native export failed: "+name)
        save("public export")
        archive("own-zone-public.f3d")
        if not exp.execute(exp.createSTEPExportOptions(str(dest/"own-zone-public.step"))):
            raise RuntimeError("Public STEP export failed")
        for proxy in reversed(proxies):
            if not proxy.deleteMe():
                raise RuntimeError("Supplier proxy removal failed")
        supplier=None
        for site in job["sites"]:
            rotation=site["rotation"]
            m=transform([list(col) for col in zip(*rotation)],site["translation"])
            if supplier is None:
                occurrence=root.occurrences.addNewComponent(m)
                supplier=occurrence.component
                supplier.name="REV-21-3005 supplier assembly"
                save("import supplier source once")
                if not app.importManager.importToTarget(app.importManager.createSTEPImportOptions(job["supplier"]),supplier):
                    raise RuntimeError("REV import failed")
                supplier.attributes.add("FRC","sourceSHA256",job["layout"]["swerve"]["sha256"])
            else:
                occurrence=root.occurrences.addExistingComponent(supplier,m)
            occurrence.attributes.add("FRC","site",site["name"])
        save("private export")
        archive("own-zone-supplier.f3d")
        # A newly created unsaved document has already been archived.
        own.close(False)
        own=None
        save("reopen supplier archive")
        own=app.importManager.importToNewDocument(app.importManager.createFusionArchiveImportOptions(str(dest/"own-zone-supplier.f3d")))
        reopened=fusion.Design.cast(own.products.itemByProductType("DesignProductType"))
        r=reopened.rootComponent
        receipt["supplierSites"]={}
        for oc in r.occurrences:
            corner=oc.attributes.itemByName("FRC","site")
            if corner:
                bounds=oc.preciseBoundingBox
                receipt["supplierSites"][corner.value]={"definition":oc.component.name,"descendants":oc.component.allOccurrences.count,"boundsMm":[round(v*10,4) for p in (bounds.minPoint,bounds.maxPoint) for v in p.asArray()],"transform":oc.transform2.asArray()}
        receipt["projectParts"]={c.name:{"bodies":c.bRepBodies.count,"extrusions":c.features.extrudeFeatures.count} for c in reopened.allComponents if c.attributes.itemByName("FRC","source")}
        if len(receipt["projectParts"])!=len(job["items"]) or len(receipt["supplierSites"])!=4:
            raise RuntimeError("Reopen inventory mismatch")
        save("complete")
    except:
        receipt["errors"].append(traceback.format_exc())
        save("failed")
        raise
    finally:
        if own and own.isValid:
            own.close(False)
        if prior and prior.isValid:
            prior.activate()
